import { atom, read, update } from 'claude-code'
import type { EngineInterface, Register, ToolCallResult } from 'claude-code'

import type { Made } from '../types'

const items = atom({ plugin: 'made-bubbles', key: 'items' } as const, [] as Made[])
const isHidden = atom({ plugin: 'made-bubbles', key: 'isHidden' } as const, false)

/** Bubbles drawn at once; older ones fold into "+N more". */
const MAX_SHOWN = 8

/**
 * Claude's own working files, not things made for the person: the scratchpad
 * and other temp files, and everything under ~/.claude (memory, settings,
 * this mod itself).
 */
const INTERNAL = /\/(appdata\/local\/temp|tmp|\.claude)\//i

const normalize = (path: string) => path.replace(/\\/g, '/')

const basename = (path: string) => normalize(path).split('/').filter(Boolean).pop() ?? path

const fileHref = (path: string) => {
  const p = normalize(path)
  return encodeURI(p.startsWith('/') ? `file://${p}` : `file:///${p}`)
}

/** Adds one item, moving it to the end if it was already there. */
const remember = async ($: EngineInterface, made: Made) => {
  await update($, items, list => [...list.filter(m => m.href !== made.href), made])
  await update($, isHidden, () => false)
}

const succeeded = (ran: ToolCallResult) => ran.deny === undefined && ran.isError !== true

const ENTITIES: Record<string, string> = { amp: '&', lt: '<', gt: '>', quot: '"', '#39': "'", apos: "'" }

/**
 * The `<title>` of a published HTML page, read from its source file (the same
 * first 8 KB the publish scans); undefined when there is none or it can't be read.
 */
async function pageTitle($: EngineInterface, path: string) {
  if (!/\.html?$/i.test(path)) return undefined
  try {
    const html = await $.fs.read(path)
    if (typeof html !== 'string') return undefined
    const match = /<title[^>]*>([\s\S]*?)<\/title>/i.exec(html.slice(0, 8192))
    const title = match?.[1]
      ?.replace(/&(amp|lt|gt|quot|#39|apos);/g, (_, name: string) => ENTITIES[name] ?? '')
      .replace(/\s+/g, ' ')
      .trim()
    return title || undefined
  } catch {
    return undefined
  }
}

/** Records a file a tool call wrote, unless the call failed or it is Claude's own. */
async function onFile($: EngineInterface, path: unknown, ran: ToolCallResult) {
  if (typeof path !== 'string' || !path || !succeeded(ran)) return
  if (INTERNAL.test(normalize(path))) return
  await remember($, { kind: 'file', label: basename(path), href: fileHref(path), path })
}

export const register: Register = on => {
  // Each tool hook only watches: if its bookkeeping throws, `.catch` hands the
  // call through untouched, so a bubble bug can never break a real write.
  on('tool.call', { tool: 'Write' }, async ($, e, next) => {
    const ran = await next(e)
    await onFile($, e.file_path, ran)
    return ran
  }).catch(($, e, next) => next(e))

  on('tool.call', { tool: 'Edit' }, async ($, e, next) => {
    const ran = await next(e)
    await onFile($, e.file_path, ran)
    return ran
  }).catch(($, e, next) => next(e))

  on('tool.call', { tool: 'NotebookEdit' }, async ($, e, next) => {
    const ran = await next(e)
    await onFile($, e.notebook_path, ran)
    return ran
  }).catch(($, e, next) => next(e))

  on('tool.call', { tool: 'Artifact' }, async ($, e, next) => {
    const ran = await next(e)
    const isPagePublish = (e.action === undefined || e.action === 'publish') && e.asset !== true
    if (!isPagePublish || !succeeded(ran)) return ran

    const result = ran.result as { url?: unknown; title?: unknown } | undefined
    const url = typeof result?.url === 'string' ? result.url : undefined
    if (!url) return ran

    const filePath = typeof e.file_path === 'string' ? e.file_path : undefined
    const label =
      (typeof result?.title === 'string' && result.title) ||
      (filePath && (await pageTitle($, filePath))) ||
      (typeof e.title === 'string' && e.title) ||
      (filePath && basename(filePath)) ||
      'Page'
    await remember($, { kind: 'page', label, href: url })
    return ran
  }).catch(($, e, next) => next(e))

  on('ui.render', { component: 'AbovePrompt' }, async ($, e, next) => {
    const list = await read($, items)
    if (e.props.hasSurvey || list.length === 0 || (await read($, isHidden))) {
      return next(e)
    }

    const { Box, Button, Link, Text } = $.ui.resolve(e)
    const shown = list.slice(-MAX_SHOWN)
    const older = list.length - shown.length
    const isTerminal = e.surface === 'terminal'

    return (
      <Box key="made" flexDirection="row" flexWrap="wrap" columnGap={1} alignItems="center">
        <Text dimColor>Made for you:</Text>
        {shown.map((m, i) => (
          <Box key={`made-${i}`} borderStyle="round" borderDimColor paddingX={1}>
            {m.kind === 'page' || isTerminal ? (
              // Pages open everywhere; a terminal also opens file:/// links.
              <Text>
                {m.kind === 'page' ? '🌐 ' : '📄 '}
                <Link href={m.href} label={m.label} />
              </Text>
            ) : (
              // The desktop app only links https:, so a file click copies its path.
              <Button
                key={`file-${i}`}
                label={`📄 ${m.label}`}
                plain
                onPress={async () => {
                  await $.ui.copy({ text: m.path ?? m.label })
                  $.ui.toast(`Copied path: ${m.path ?? m.label}`)
                }}
              />
            )}
          </Box>
        ))}
        {older > 0 ? <Text dimColor>+{older} more</Text> : null}
        <Button
          key="clear"
          label="Clear"
          plain
          dimColor
          onPress={async () => {
            await update($, items, () => [])
          }}
        />
        <Button
          key="hide"
          label="Hide"
          plain
          dimColor
          onPress={() => update($, isHidden, () => true)}
        />
      </Box>
    )
  })
}

