/** One thing Claude made: a local file it wrote, or a page it published. */
export type Made = {
  kind: 'file' | 'page'
  /** Short name shown in the bubble. */
  label: string
  /** What a click opens: a file:/// URL or the page's https URL. */
  href: string
  /** For a file, its full path as written (copied by a click on desktop). */
  path?: string
}

declare module 'claude-code' {
  interface PluginState {
    'made-bubbles': { items: Made[]; isHidden: boolean }
  }
}
